    if (shouldBulletOnSpace(value, caret)) {
      event.preventDefault();
      blocks[index].bullet = true;
      blocks[index].text = "";
      renderOutliner(outliner, blocks, blocks[index].id, 0);
      scheduleSave(outliner);
      return;
    }
    if (!shouldIndentOnSpace(value, caret)) return;
